{
 public SupplierRmaCapaGovernanceActionHistoryWindow(SupplierRmaCapaGovernanceAction item,SupplierRmaCapaGovernanceActionService service){Title="Storico azione Governance CAPA";Width=850;Height=600;WindowStartupLocation=WindowStartupLocation.CenterOwner;var root=new StackPanel{Margin=new Thickness(24),Spacing=8,Children={new TextBlock{Text="Storico azione",FontSize=26,FontWeight=FontWeight.Bold},new TextBlock{Text=item.Title,TextWrapping=TextWrapping.Wrap}}};foreach(var x in service.History(item.Id))root.Children.Add(new Border{Padding=new Thickness(10),BorderBrush=UiTokens.Brush(UiTokens.Border),BorderThickness=new Thickness(0,0,0,1),Child=new StackPanel{Children={new TextBlock{Text=$"{x.EventType} · {Date(x.CreatedAt)}",FontWeight=FontWeight.Bold},new TextBlock{Text=x.Detail,TextWrapping=TextWrapping.Wrap},new TextBlock{Text=$"Operatore: {x.CreatedBy}",Foreground=UiTokens.Brush(UiTokens.TextSecondary)}}}});Content=new ScrollViewer{Content=root};}private static string Date(string v)=>DateTime.TryParse(v,out var d)?d.ToString("dd/MM/yyyy HH:mm"):v;
